int vc4_prepare_binning_cmdlist(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret = 0;
    size_t binning_cmdlist_size = 0;
    size_t shader_records_size = 0;
    size_t uniforms_size = 0;
    void *binning_cmdlist = NULL;
    void *shader_records = NULL;
    void *uniforms = NULL;
    struct drm_gem_cma_object *bo = NULL;

    if (!dev || !exec) {
        return -EINVAL;
    }

    if (exec->binning_cmdlist_arg.size > INT_MAX ||
        exec->shader_records_arg.size > INT_MAX ||
        exec->uniforms_arg.size > INT_MAX) {
        return -EINVAL;
    }

    binning_cmdlist_size = exec->binning_cmdlist_arg.size;
    shader_records_size = exec->shader_records_arg.size;
    uniforms_size = exec->uniforms_arg.size;

    binning_cmdlist = kmalloc(binning_cmdlist_size, GFP_KERNEL);
    if (!binning_cmdlist) {
        ret = -ENOMEM;
        goto cleanup;
    }

    shader_records = kmalloc(shader_records_size, GFP_KERNEL);
    if (!shader_records) {
        ret = -ENOMEM;
        goto cleanup;
    }

    uniforms = kmalloc(uniforms_size, GFP_KERNEL);
    if (!uniforms) {
        ret = -ENOMEM;
        goto cleanup;
    }

    if (copy_from_user(binning_cmdlist, exec->binning_cmdlist_arg.ptr,
                       binning_cmdlist_size)) {
        ret = -EFAULT;
        goto cleanup;
    }

    if (copy_from_user(shader_records, exec->shader_records_arg.ptr,
                       shader_records_size)) {
        ret = -EFAULT;
        goto cleanup;
    }

    if (copy_from_user(uniforms, exec->uniforms_arg.ptr, uniforms_size)) {
        ret = -EFAULT;
        goto cleanup;
    }

    bo = drm_gem_cma_create(dev, binning_cmdlist_size + shader_records_size + uniforms_size);
    if (!bo) {
        ret = -ENOMEM;
        goto cleanup;
    }

    if (drm_gem_cma_vmap(bo, &exec->vaddr)) {
        ret = -ENOMEM;
        goto cleanup;
    }

    memcpy(exec->vaddr, binning_cmdlist, binning_cmdlist_size);
    memcpy(exec->vaddr + binning_cmdlist_size, shader_records, shader_records_size);
    memcpy(exec->vaddr + binning_cmdlist_size + shader_records_size, uniforms, uniforms_size);

    ret = vc4_validate_cmdlist(dev, exec->vaddr, binning_cmdlist_size);
    if (ret) {
        goto cleanup;
    }

    ret = vc4_wait_for_rendering(dev);
    if (ret) {
        goto cleanup;
    }

    return 0;

 cleanup:
    kfree(binning_cmdlist);
    kfree(shader_records);
    kfree(uniforms);
    if (bo) {
        drm_gem_cma_unmap(bo);
        drm_gem_object_put(&bo->base);
    }
    return ret;
}
